WITH kept AS (SELECT s.* FROM suppliers s WHERE NOT EXISTS (SELECT 1 FROM products c WHERE c.supplier_id = s.id AND ARRAY_CONTAINS(c.tags, 'clearance'))) SELECT country, SORT_ARRAY(COLLECT_SET(city)) AS city_list, APPROX_PERCENTILE(rating, ARRAY(0.25, 0.5, 0.75)) AS rating_quartiles, ROUND(AVG(rating), 2) AS avg_rating, ROUND(AVG(rating), 2) AS avg_rating_2, COUNT(DISTINCT id) AS distinct_ids, PERCENTILE_APPROX(rating, ARRAY(0.25, 0.5, 0.75)) AS rating_quartiles_2 FROM kept GROUP BY 1 ORDER BY distinct_ids DESC
